Q: Cannot understand scrollbar program from Charles Petzold&#39;s &quot;Programming Windows, 5th Edition&quot; A: <p>Like I said all you have to do i copy/paste and compile and the program will work as intended. So (1 - iHorzPos) is correct.</p>
<p>I have checked the behavior of the values of variables as the program is running adding this :</p>
<pre><code> //Find Painting Limits

 iPaintBegin = max(0, iVertPos + PaintStruct.rcPaint.top / cyChar);
 iPaintEnd = min(NUMLINES - 1,
     iVertPos + PaintStruct.rcPaint.bottom / cyChar);

 //Print Painting Limits to Console
 //Calculates which lines from sysmets have to be painted/displayed 
 //everytime we adjust the window.
 OutputDebugStringA(&quot;\n-----------------------------------------------------------\n&quot;);
 char charBuffer2[4] = &quot;&quot;;
 _itoa(PaintStruct.rcPaint.top, charBuffer2, 10);
 OutputDebugStringA(&quot;\n&quot;);
 OutputDebugStringA(&quot;PaintStruct.rcPaint.top : &quot;);
 OutputDebugStringA(charBuffer2);

 _itoa(PaintStruct.rcPaint.bottom, charBuffer2, 10);
 OutputDebugStringA(&quot;\n&quot;);
 OutputDebugStringA(&quot;PaintStruct.rcPaint.bottom : &quot;);
 OutputDebugStringA(charBuffer2);

 _itoa(cyChar, charBuffer2, 10);
 OutputDebugStringA(&quot;\n&quot;);
 OutputDebugStringA(&quot;cyChar : &quot;);
 OutputDebugStringA(charBuffer2);

 _itoa(PaintStruct.rcPaint.top / cyChar, charBuffer2, 10);
 OutputDebugStringA(&quot;\n&quot;);
 OutputDebugStringA(&quot;PaintStruct.rcPaint.top / cyChar : &quot;);
 OutputDebugStringA(charBuffer2);

 _itoa(PaintStruct.rcPaint.bottom / cyChar, charBuffer2, 10);
 OutputDebugStringA(&quot;\n&quot;);
 OutputDebugStringA(&quot;PaintStruct.rcPaint.bottom / cyChar : &quot;);
 OutputDebugStringA(charBuffer2);

 _itoa(iVertPos, charBuffer2, 10);
 OutputDebugStringA(&quot;\n&quot;);
 OutputDebugStringA(&quot;iVertPos : &quot;);
 OutputDebugStringA(charBuffer2);

 _itoa(NUMLINES - 1, charBuffer2, 10);
 OutputDebugStringA(&quot;\n&quot;);
 OutputDebugStringA(&quot;NUMLINES - 1 : &quot;);
 OutputDebugStringA(charBuffer2);

 _itoa(iVertPos + PaintStruct.rcPaint.top / cyChar, charBuffer2, 10);
 OutputDebugStringA(&quot;\n&quot;);
 OutputDebugStringA(&quot;iPaintBegin : iVertPos + PaintStruct.rcPaint.top / cyChar : &quot;);
 OutputDebugStringA(charBuffer2);

 _itoa(iVertPos + PaintStruct.rcPaint.bottom / cyChar, charBuffer2, 10);
 OutputDebugStringA(&quot;\n&quot;);
 OutputDebugStringA(&quot;iPaintEnd : iVertPos + PaintStruct.rcPaint.bottom / cyChar : &quot;);
